input.command:
cat > "$TMPDIR/probe.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-2bQq3v/project/node_modules/playwright-core');
(async () => {
  const base = process.env.BASE;
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const failed = [];
  page.on('requestfailed', r => failed.push(['FAILED', r.url(), r.failure()?.errorText]));
  page.on('response', r => { if (r.status() >= 400) failed.push([r.status(), r.url()]); });
  for (const p of ['index','products','pricing','orders','about','contact']) {
    await page.goto(`${base}/${p}.html`, { waitUntil: 'networkidle' });
    const info = await page.evaluate(() => {
      const body = getComputedStyle(document.body);
      const h1 = document.querySelector('h1');
      return {
        fontFamily: body.fontFamily,
        fontSize: body.fontSize,
        lineHeight: body.lineHeight,
        bodyColor: body.color,
        bg: body.backgroundColor,
        h1: h1 ? { size: getComputedStyle(h1).fontSize, family: getComputedStyle(h1).fontFamily } : null,
        fonts: [...document.fonts].map(f => `${f.family}:${f.status}`),
      };
    });
    console.log(p, JSON.stringify(info));
  }
  console.log('FAILED_REQUESTS', JSON.stringify(failed, null, 2));
  await browser.close();
})();
EOF
PORT=${PORT} node server.js > "$TMPDIR/server.log" 2>&1 &
echo $! > "$TMPDIR/server.pid"
sleep 1
BASE="http://127.0.0.1:$PORT" node "$TMPDIR/probe.js"

